UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbe-622fr-ft.pdf',
  descripcion_larga_es = $d$La silla de ruedas estándar en acero con Rin Estrella 22" y  freno de asistencia está diseñada para brindar soporte, estabilidad y confort en el uso diario de personas con movilidad reducida. Su estructura en acero ofrece resistencia y durabilidad, siendo adecuada tanto para el hogar como para entornos institucionales o clínicos. Su diseño clásico y funcional permite un desplazamiento seguro y estable, su freno de asistencia permite el uso seguro por personas cuidadoras o familiares.

La silla de ruedas estándar en acero con freno de cuidador Konfort Plus (KBE-622FR) incorpora un freno de asistencia que permite al acompañante controlarla. Pesa 14,5 kg, tiene asiento de 46 cm de ancho, capacidad de 100 kg, 62 cm de ancho total (26 cm plegada), color verde oscuro y 2 años de garantía.$d$,
  descripcion_larga_en = $d$The standard steel wheelchair with 22" star wheel and assistive brake is designed to provide support, stability and comfort for daily use by people with reduced mobility. Its steel structure offers resistance and durability, making it suitable for both home and institutional or clinical settings. Its classic and functional design allows safe and stable movement, and the assistive brake enables safe use by caregivers or family members.

The Konfort Plus standard steel wheelchair with caregiver brake (KBE-622FR) includes an assistance brake that lets the companion control it. It weighs 14.5 kg, has a 46 cm wide seat, 100 kg capacity, 62 cm overall width (26 cm folded), dark green colour and a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-622FR"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"14,5 kg"},{"clave":"Ancho de asiento / total","grupo":"Dimensiones","valor":"46 cm / 62 cm"},{"clave":"Freno","grupo":"Seguridad","valor":"De cuidador"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Freno de cuidador para que el acompañante controle la silla.","Asiento de 46 cm y capacidad de 100 kg.","Estructura de acero plegable (26 cm) con 2 años de garantía."],"beneficios_en":["Caregiver brake so the companion can control the chair.","46 cm seat and 100 kg capacity.","Foldable steel structure (26 cm) with 2-year warranty."],"valor_es":"Una silla de ruedas de acero con freno de cuidador.","valor_en":"A steel wheelchair with caregiver brake.","preguntas_frecuentes_es":[{"q":"¿Tiene freno para el acompañante?","a":"Sí, incorpora freno de cuidador."},{"q":"¿Qué peso soporta?","a":"100 kg."},{"q":"¿De qué color es?","a":"Verde oscuro."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar en Acero con Rin Estrella 22\" y  Freno de Asistencia de 45,7 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Does it have a brake for the companion?","a":"Yes, it includes a caregiver brake."},{"q":"What weight does it support?","a":"100 kg."},{"q":"What colour is it?","a":"Dark green."},{"q":"Where can I download the Standard Steel Wheelchair with 22\" Star Wheel and Assistive Brake, 45.7 cm width datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas con freno de cuidador","silla de ruedas KBE-622FR","silla de ruedas de acero","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-622FR"],"seo_keywords_en":["wheelchair with caregiver brake","KBE-622FR wheelchair","steel wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KBE-622FR datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCVQD536U4UZAMBB63GNFVC7W66U?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-estandar-en-acero-con-rin-estrella-22-y-freno-de-asistencia-de-45-ref-kbe-622fr';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbe-982e-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar con Rín Estrella es ideal para la movilidad cotidiana, pensada para personas que requieren apoyo estable, cómodo y funcional en desplazamientos cortos. Su estructura resistente y su diseño clásico facilitan un uso seguro tanto en casa como en exteriores. El rín de estrella aporta mayor rigidez y estabilidad a las ruedas traseras, permitiendo un desplazamiento más fluido. Ligera, plegable y fácil de transportar, particularmente gracias a sus reposapies removibles esta silla acompaña rutinas diarias, visitas, trámites, paseos y todas esas escenas donde la movilidad necesita ser sencilla y confiable.

La silla de ruedas estándar con rin estrella Konfort Plus (KBE-982E) es de acero con recubrimiento electrostático negro, pensada como solución confiable en entornos de alta afluencia (centros comerciales, aeropuertos) o uso domiciliario. Tiene tapicería de nailon ignífugo acolchado, apoyabrazos removibles con tornillo y tuerca, respaldo removible con clip, asiento de 46 cm y pesa 15,2 kg.$d$,
  descripcion_larga_en = $d$The Standard Wheelchair with Star Rim is ideal for daily mobility, designed for users requiring stable, comfortable and functional support for short trips. Its sturdy frame and classic design enable safe use both at home and outdoors. The star rim provides increased rigidity and stability to the rear wheels, allowing smoother movement. Lightweight, foldable and easy to transport, especially with removable footrests, this wheelchair supports daily routines, visits, errands, walks and all scenarios where mobility needs to be simple and reliable.

The Konfort Plus standard star-rim wheelchair (KBE-982E) is steel with black electrostatic coating, designed as a reliable solution in high-traffic settings (shopping centres, airports) or home use. It has flame-retardant padded nylon upholstery, removable armrests with bolt and nut, a removable backrest with clip, a 46 cm seat and weighs 15.2 kg.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-982E"},{"clave":"Peso neto","grupo":"Peso","valor":"15,2 kg"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"46 cm"},{"clave":"Estructura","grupo":"Material","valor":"Acero, tubo de 22 mm x 1,5 mm, pintura electrostática"},{"clave":"Tapicería","grupo":"Material","valor":"Nailon ignífugo acolchado"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Acero con pintura electrostática negra y tapicería ignífuga acolchada.","Apoyabrazos y respaldo removibles.","Asiento de 46 cm y 15,2 kg."],"beneficios_en":["Steel with black electrostatic paint and flame-retardant padded upholstery.","Removable armrests and backrest.","46 cm seat and 15.2 kg."],"valor_es":"Una silla de ruedas estándar de acero con apoyabrazos removibles.","valor_en":"A standard steel wheelchair with removable armrests.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"15,2 kg."},{"q":"¿Qué tapicería tiene?","a":"Nailon ignífugo acolchado."},{"q":"¿Son removibles los apoyabrazos?","a":"Sí, con tornillo y tuerca."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar con Rin estrella de 46 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"15.2 kg."},{"q":"What upholstery does it have?","a":"Flame-retardant padded nylon."},{"q":"Are the armrests removable?","a":"Yes, with bolt and nut."},{"q":"Where can I download the Standard Wheelchair with 46 cm Star Rim datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas estándar negra","silla de ruedas KBE-982E","silla de ruedas rin estrella","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-982E"],"seo_keywords_en":["black standard wheelchair","KBE-982E wheelchair","star-rim wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KBE-982E datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCCLU2WPXIOBFVHGV5M6LZ4ULBVI?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-estandar-con-rin-estrella-de-46-cm-de-ancho-ref-kbe-982e';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbe-9000d-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar con Rin Estrella KP está diseñada para ofrecer movilidad confiable, confort y resistencia en el uso diario. Fabricada con una estructura robusta de acero de alta calidad y tapicería en poliéster resistente, combina durabilidad y facilidad de manejo para usuarios y cuidadores. Su diseño plegable y su peso equilibrado permiten fácil transporte y almacenamiento.

La silla de ruedas estándar con rin estrella Konfort Plus (KBE-9000D) está diseñada para ofrecer movilidad confiable, confort y resistencia en el uso diario, con estructura robusta de acero de alta calidad (tubo de 22,3 mm, calibre 1,2 mm) y tapicería de poliéster resistente. Su diseño plegable (23,5 cm plegada) y su peso equilibrado facilitan el transporte y el almacenamiento.$d$,
  descripcion_larga_en = $d$Standard wheelchair with KP star rim designed to provide reliable mobility, comfort and durability for daily use. Made with a robust high-quality steel structure and resistant polyester upholstery, it combines durability and ease of handling for users and caregivers. Its foldable design and balanced weight allow easy transport and storage.

The Konfort Plus standard star-rim wheelchair (KBE-9000D) is designed to offer reliable mobility, comfort and strength for daily use, with a robust high-quality steel structure (22.3 mm tube, 1.2 mm gauge) and durable polyester upholstery. Its folding design (23.5 cm folded) and balanced weight make it easy to transport and store.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-9000D"},{"clave":"Ancho plegada","grupo":"Dimensiones","valor":"23,5 cm"},{"clave":"Estructura","grupo":"Material","valor":"Acero; tubo 22,3 mm, calibre 1,2 mm"},{"clave":"Tapicería","grupo":"Material","valor":"Poliéster"},{"clave":"Color","grupo":"Color","valor":"Negro"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Estructura de acero de alta calidad y tapicería de poliéster resistente.","Plegable a 23,5 cm para transportar y almacenar fácilmente.","Pensada para usuarios y cuidadores en el uso diario."],"beneficios_en":["High-quality steel structure and durable polyester upholstery.","Folds to 23.5 cm for easy transport and storage.","Designed for users and caregivers in daily use."],"valor_es":"Una silla de ruedas estándar plegable de acero con tapicería de poliéster.","valor_en":"A standard foldable steel wheelchair with polyester upholstery.","preguntas_frecuentes_es":[{"q":"¿Cuánto mide plegada?","a":"23,5 cm de ancho."},{"q":"¿De qué material es la tapicería?","a":"Poliéster."},{"q":"¿Qué color tiene?","a":"Negro."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar Con Rin Estrella KP?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How wide is it folded?","a":"23.5 cm."},{"q":"What is the upholstery made of?","a":"Polyester."},{"q":"What colour is it?","a":"Black."},{"q":"Where can I download the Standard Wheelchair with KP Star Rim datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas estándar KP","silla de ruedas KBE-9000D","silla de ruedas plegable de acero","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-9000D"],"seo_keywords_en":["KP standard wheelchair","KBE-9000D wheelchair","foldable steel wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KBE-9000D datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCITGT7LLYWFBPTKIZEWI4IJAVAY?version=4.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-estandar-con-rin-estrella-kp-ref-kbe-9000d';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kbe-9110hc-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas modelo KBE-9110HC es un equipo de apoyo a la movilidad diseñado para usuarios con necesidades de traslado temporal o permanente. Está pensada para ofrecer estabilidad y confort en entornos clínicos y domiciliarios, e incluye características que facilitan la transferencia y el manejo por parte de cuidadores. Es una solución práctica para la movilización de pacientes en instituciones de salud y hogares.

La silla de ruedas Konfort Plus KBE-9110HC es estándar, de acero color gris, con rueda trasera de rin radio, respaldo fijo, reposapiés fijos removibles y apoyabrazos fijos. Su tapicería es de nailon acolchado y pesa 12,5 kg. Es ideal para establecimientos donde se presta asistencia a usuarios, como centros comerciales, aeropuertos y conjuntos residenciales.$d$,
  descripcion_larga_en = $d$The Wheelchair model KBE-9110HC is a mobility support equipment designed for users requiring temporary or permanent transfer needs. It is designed to offer stability and comfort in clinical and home environments, and includes features that facilitate transfer and handling by caregivers. A practical solution for patient mobilization in healthcare institutions and homes.

The Konfort Plus KBE-9110HC wheelchair is a standard grey steel chair with spoked rear wheels, fixed backrest, fixed removable footrests and fixed armrests. Its upholstery is padded nylon and it weighs 12.5 kg. It is ideal for establishments that assist users, such as shopping centres, airports and residential complexes.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-9110HC"},{"clave":"Peso neto","grupo":"Peso","valor":"12,5 kg"},{"clave":"Estructura / tapicería","grupo":"Material","valor":"Acero gris / nailon acolchado"},{"clave":"Apoyabrazos / reposapiés","grupo":"Configuración","valor":"Fijos / fijos removibles"},{"clave":"Trasera","grupo":"Ruedas","valor":"Rin radio"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Acero gris con rueda trasera de rin radio y tapicería de nailon acolchado.","Reposapiés removibles y apoyabrazos fijos.","Ideal para préstamo de sillas en centros comerciales, aeropuertos y conjuntos residenciales."],"beneficios_en":["Grey steel with spoked rear wheels and padded nylon upholstery.","Removable footrests and fixed armrests.","Ideal for loaner chairs in shopping centres, airports and residential complexes."],"valor_es":"Una silla de ruedas estándar de acero, ligera y apta para uso institucional.","valor_en":"A light standard steel wheelchair suitable for institutional use.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"12,5 kg (neto, según la ficha)."},{"q":"¿Para qué entornos es?","a":"Establecimientos que prestan asistencia: centros comerciales, aeropuertos y conjuntos residenciales."},{"q":"¿Qué reposapiés tiene?","a":"Fijos removibles."},{"q":"¿Dónde descargo la ficha técnica de Silla de ruedas?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"12.5 kg (net, per the datasheet)."},{"q":"Which settings is it for?","a":"Establishments that assist users: shopping centres, airports and residential complexes."},{"q":"Which footrests does it have?","a":"Fixed removable."},{"q":"Where can I download the Wheelchair datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas estándar gris","silla de ruedas KBE-9110HC","silla de ruedas para centros comerciales","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-9110HC"],"seo_keywords_en":["grey standard wheelchair","KBE-9110HC wheelchair","shopping centre wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KBE-9110HC datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC6DXHH7RM3NFWNFERDWRRIXCTII?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
