UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe9119f-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar KBE9119F es ideal para quienes necesitan ayuda para movilizarse por un rato y realizar transferencias de manera autónoma y segura. Fabricada en acero martillado, esta silla ofrece una estructura resistente y duradera, perfecta para uso en interiores. Sus reposapiés fijos, desarmables mediante pin, facilitan el transporte y almacenamiento. Los apoyabrazos abatibles proporcionan comodidad y facilidad para realizar transferencias laterales.

La silla de ruedas estándar Konfort Plus KBE9119F es de acero, con ruedas traseras de rin radio, asas de empuje abatibles, reposapiés fijos abatibles, apoyabrazos abatibles y tapicería de nailon acolchada. Es para quienes necesitan ayuda para movilizarse por un rato y realizar transferencias de forma autónoma y segura, sin necesidad de transportar o guardar su propia silla.$d$,
  descripcion_larga_en = $d$The KBE9119F standard wheelchair is designed for users requiring short-term mobility assistance and safe, autonomous transfers. Constructed in hammered steel, it offers a resistant and durable structure suitable for indoor use. Its fixed footrests, removable by pin, facilitate transport and storage. The foldable armrests provide comfort and ease for lateral transfers.

The Konfort Plus KBE9119F standard wheelchair is steel, with spoked rear wheels, folding push handles, folding fixed footrests, folding armrests and padded nylon upholstery. It is for those who need help getting around for a while and to carry out transfers independently and safely, without needing to carry or store their own chair.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE9119F"},{"clave":"Estructura / tapicería","grupo":"Material","valor":"Acero / nailon acolchado"},{"clave":"Apoyabrazos","grupo":"Configuración","valor":"Abatibles"},{"clave":"Traseras","grupo":"Ruedas","valor":"Rin radio"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Apoyabrazos, asas y reposapiés abatibles que facilitan las transferencias.","Tapicería de nailon acolchada y ruedas traseras de rin radio.","Ideal para préstamo o uso temporal sin llevar la silla propia."],"beneficios_en":["Folding armrests, handles and footrests that ease transfers.","Padded nylon upholstery and spoked rear wheels.","Ideal for loan or temporary use without carrying your own chair."],"valor_es":"Una silla de ruedas estándar con apoyabrazos abatibles.","valor_en":"A standard wheelchair with folding armrests.","preguntas_frecuentes_es":[{"q":"¿Qué facilita las transferencias?","a":"Los apoyabrazos abatibles, junto con las asas y reposapiés abatibles."},{"q":"¿Cómo es la tapicería?","a":"Nailon acolchado."},{"q":"¿Para quién es?","a":"Para quienes necesitan movilizarse por un rato y hacer transferencias de forma autónoma y segura."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar En Acero Con Apoyabrazos Abatibles Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What eases transfers?","a":"The folding armrests, together with folding handles and footrests."},{"q":"What is the upholstery like?","a":"Padded nylon."},{"q":"Who is it for?","a":"Those who need to get around for a while and transfer independently and safely."},{"q":"Where can I download the Standard Wheelchair in Steel With Foldable Armrests Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas con apoyabrazos abatibles","silla de ruedas KBE9119F","silla de ruedas estándar de acero","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE9119F"],"seo_keywords_en":["wheelchair with folding armrests","KBE9119F wheelchair","standard steel wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KBE9119F datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCXBBQ2ZGBZRG3BMZIOVHXU4INZM?version=6.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
