UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe-9125t-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas de Transporte KBE-9125T es una opción robusta y confiable para quienes buscan una solución de movilidad en entornos interiores. Fabricada en acero resistente y equipada con ruedas traseras de 14 1/4 pulgadas y delanteras de 6 pulgadas, ambas con corazas macizas en poliuretano (PU), esta silla ofrece estabilidad y durabilidad en cada uso.

La silla de ruedas de transporte básica Konfort Plus KBE-9125T es de acero, plegable, con apoyabrazos fijos, reposapiés fijos y frenos de cuidador. Tiene ruedas traseras y delanteras de PU con corazas macizas, tapicería de lona acolchada y capacidad de hasta 100 kg. Es ideal para quien necesita una silla para interiores con cuidador, y tiene 1 año de garantía.$d$,
  descripcion_larga_en = $d$The KBE-9125T Transport Wheelchair is a robust and reliable option for mobility solutions in indoor environments. Made of resistant steel and equipped with 14 1/4 inch rear wheels and 6 inch front wheels, both with solid polyurethane (PU) hubs, this wheelchair offers stability and durability in each use.

The Konfort Plus KBE-9125T basic transport wheelchair is steel, foldable, with fixed armrests, fixed footrests and caregiver brakes. It has PU rear and front wheels with solid tyres, padded canvas upholstery and capacity up to 100 kg. It is ideal for someone who needs an indoor chair with a caregiver, and has a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-9125T"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Estructura / tapicería","grupo":"Material","valor":"Acero / lona acolchada"},{"clave":"Freno","grupo":"Seguridad","valor":"De cuidador"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Frenos de cuidador y estructura plegable de acero.","Capacidad de hasta 100 kg y tapicería de lona acolchada.","Ruedas de PU con corazas macizas; 1 año de garantía."],"beneficios_en":["Caregiver brakes and foldable steel structure.","Up to 100 kg capacity and padded canvas upholstery.","PU wheels with solid tyres; 1-year warranty."],"valor_es":"Una silla de ruedas de transporte básica de acero con frenos de cuidador.","valor_en":"A basic steel transport wheelchair with caregiver brakes.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 100 kg."},{"q":"¿Quién la controla?","a":"El cuidador, mediante frenos de cuidador."},{"q":"¿Qué garantía tiene?","a":"1 año."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas De Transporte Básica En Acero Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 100 kg."},{"q":"Who controls it?","a":"The caregiver, through caregiver brakes."},{"q":"What warranty does it have?","a":"1 year."},{"q":"Where can I download the Basic Steel Transport Wheelchair Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas de transporte","silla de ruedas KBE-9125T","silla de transporte con frenos de cuidador","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-9125T"],"seo_keywords_en":["transport wheelchair","KBE-9125T wheelchair","transport chair with caregiver brakes","Konfort Plus wheelchair","wheelchairs Colombia","KBE-9125T datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC6OP6TREDA5FHDIDHF662YBHMLA?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
