UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbo1432rf-mp23-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas de Transporte en Acero de Konfort Plus, es la elección perfecta para quienes buscan una silla de transporte robusta, cómoda y fácil de manejar. Fabricada en acero pintado, esta silla ofrece una estructura duradera y estable, asegurando la seguridad del usuario en todo momento. Su diseño plegable y respaldo abatible permiten un almacenamiento compacto, ideal para espacios reducidos y transporte en viajes. Los reposapiés desarmables facilitan el transporte de la silla.

La silla de ruedas de transporte T50 Konfort Plus (KBO1432RF-MP23) tiene estructura liviana, plegable y fácil de maniobrar en acero pintado, respaldo abatible y reposapiés desarmable que ayudan al cuidador en el transporte. Sus frenos de cuidador dan total control a quien la conduce; soporta hasta 90 kg, tiene tapicería acolchada y 1 año de garantía.$d$,
  descripcion_larga_en = $d$Transport wheelchair made of painted steel with a durable and stable structure. Foldable design with reclining backrest for compact storage. Removable footrests for easy transport. Ideal for hospitalization, outpatient care, and emergency services.

The Konfort Plus T50 transport wheelchair (KBO1432RF-MP23) has a lightweight, foldable, easy-to-manoeuvre painted-steel structure, a folding backrest and detachable footrests that help the caregiver during transport. Its caregiver brakes give full control to the person pushing; it supports up to 90 kg, has padded upholstery and a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBO1432RF-MP23"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Estructura","grupo":"Material","valor":"Acero pintado, gris"},{"clave":"Freno","grupo":"Seguridad","valor":"De cuidador"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Acero pintado plegable con respaldo abatible y reposapiés desarmable.","Frenos de cuidador y capacidad de hasta 90 kg.","Tapicería acolchada y 1 año de garantía."],"beneficios_en":["Foldable painted steel with folding backrest and detachable footrests.","Caregiver brakes and capacity up to 90 kg.","Padded upholstery and 1-year warranty."],"valor_es":"Una silla de ruedas de transporte de acero con respaldo abatible.","valor_en":"A steel transport wheelchair with folding backrest.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 90 kg."},{"q":"¿De qué color es?","a":"Gris."},{"q":"¿Qué garantía tiene?","a":"1 año."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas De Transporte En Acero Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 90 kg."},{"q":"What colour is it?","a":"Grey."},{"q":"What warranty does it have?","a":"1 year."},{"q":"Where can I download the Steel Transport Wheelchair, Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas de transporte T50","silla de ruedas KBO1432RF","silla de transporte de acero","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBO1432RF-MP23"],"seo_keywords_en":["T50 transport wheelchair","KBO1432RF wheelchair","steel transport chair","Konfort Plus wheelchair","wheelchairs Colombia","KBO1432RF-MP23 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCDAQN4A7NUZC6TPRGYUK4WSI7CM?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-de-transporte-en-acero-ref-kbo1432rf-mp23-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe1432rf-mp23l-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas de Transporte en Aluminio Konfort Plus es la solución ideal para quienes buscan una combinación de ligereza, durabilidad y comodidad en una silla de transporte. Fabricada en aluminio liviano y pintada en un elegante color gris, esta silla es fácil de maniobrar y transportar, siendo perfecta tanto para el usuario como para el cuidador.

La silla de ruedas de transporte T100 Konfort Plus (KBE1432RF-MP23L) tiene estructura liviana y plegable en aluminio que da estabilidad al usuario. Su respaldo abatible y reposapiés ajustable en 3 posiciones ayudan al cuidador en las transferencias y el transporte. Cuenta con frenos de cuidador, apoyabrazos abatibles, tapicería acolchada, capacidad de 90 kg y 1 año de garantía.$d$,
  descripcion_larga_en = $d$The Aluminum Transport Wheelchair Konfort Plus is the ideal solution for those seeking a combination of lightness, durability, and comfort in a transport chair. Made from lightweight aluminum and finished in an elegant gray color, it is easy to maneuver and transport, making it perfect for both users and caregivers.

The Konfort Plus T100 transport wheelchair (KBE1432RF-MP23L) has a lightweight, foldable aluminium structure that gives the user stability. Its folding backrest and footrest adjustable in 3 positions help the caregiver with transfers and transport. It has caregiver brakes, folding armrests, padded upholstery, 90 kg capacity and a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE1432RF-MP23L"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio"},{"clave":"Reposapiés","grupo":"Ajustes","valor":"3 posiciones"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio liviano y plegable con apoyabrazos abatibles.","Reposapiés ajustable en 3 posiciones y respaldo abatible.","Frenos de cuidador; capacidad de 90 kg; 1 año de garantía."],"beneficios_en":["Lightweight foldable aluminium with folding armrests.","Footrest adjustable in 3 positions and folding backrest.","Caregiver brakes; 90 kg capacity; 1-year warranty."],"valor_es":"Una silla de ruedas de transporte de aluminio con reposapiés de 3 posiciones.","valor_en":"An aluminium transport wheelchair with 3-position footrest.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 90 kg."},{"q":"¿Cuántas posiciones tiene el reposapiés?","a":"3 posiciones."},{"q":"¿De qué material es?","a":"Aluminio."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas De Transporte En Aluminio Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 90 kg."},{"q":"How many footrest positions does it have?","a":"3 positions."},{"q":"What material is it?","a":"Aluminium."},{"q":"Where can I download the Aluminum Transport Wheelchair Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas de transporte de aluminio","silla de ruedas T100","silla de transporte liviana","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE1432RF-MP23L"],"seo_keywords_en":["aluminium transport wheelchair","T100 wheelchair","lightweight transport chair","Konfort Plus wheelchair","wheelchairs Colombia","KBE1432RF-MP23L datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCORBCTO34EZBPLOPJXGG76L5ENU?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-de-transporte-en-aluminio-ref-kbe1432rf-mp23l-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9806l-ft.pdf',
  descripcion_larga_es = $d$Silla de ruedas de transporte fabricada en aluminio tipo avión, diseñada para ofrecer ligereza, resistencia y facilidad de manejo en traslados cortos. Cuenta con un diseño compacto que facilita el desplazamiento en espacios reducidos. Está pensada para ser empujada por un acompañante, permitiendo un transporte práctico y funcional.

La silla de ruedas viajera ultraliviana Konfort Plus (tipo avión, KP9806L) tiene marco de aluminio y soporte del respaldo en acero, y está pensada para ligereza, resistencia y facilidad de manejo en traslados cortos. Pesa 9 kg, mide 51,5 cm de ancho y 87,5 cm de alto, soporta 100 kg, tiene frenos de cuidador con bloqueo y se impulsa por un acompañante; garantía de 1 año.$d$,
  descripcion_larga_en = $d$Transport wheelchair made of airplane aluminum, designed for lightness, resistance and easy handling on short trips. It features a compact design that facilitates movement in reduced spaces. Designed to be pushed by an attendant, allowing practical and functional transport.

The Konfort Plus ultralight travel wheelchair (aircraft type, KP9806L) has an aluminium frame and steel backrest support, and is designed for lightness, strength and easy handling on short transfers. It weighs 9 kg, measures 51.5 cm wide and 87.5 cm high, supports 100 kg, has locking caregiver brakes and is pushed by a companion; 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9806L"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"9 kg"},{"clave":"Ancho / alto total","grupo":"Dimensiones","valor":"51,5 cm / 87,5 cm"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2017DM-0017305; clase I"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Solo 9 kg, con marco de aluminio plegable.","Compacta (51,5 cm de ancho) para espacios reducidos.","Freno de cuidador con bloqueo; capacidad de 100 kg."],"beneficios_en":["Only 9 kg, with foldable aluminium frame.","Compact (51.5 cm wide) for tight spaces.","Locking caregiver brake; 100 kg capacity."],"valor_es":"Una silla de ruedas ultraliviana de 9 kg para traslados cortos.","valor_en":"A 9 kg ultralight wheelchair for short transfers.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"9 kg."},{"q":"¿Quién la impulsa?","a":"Un acompañante; está pensada para traslados cortos."},{"q":"¿Qué capacidad tiene?","a":"100 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla de Ruedas De Transporte en Aluminio Tipo Avión?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"9 kg."},{"q":"Who pushes it?","a":"A companion; it is designed for short transfers."},{"q":"What capacity does it have?","a":"100 kg."},{"q":"Where can I download the Airplane-Type Aluminum Transport Wheelchair datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas viajera ultraliviana","silla de ruedas tipo avión","silla de ruedas de aluminio KP9806L","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KP9806L"],"seo_keywords_en":["ultralight travel wheelchair","aircraft-type wheelchair","KP9806L aluminium wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KP9806L datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC3XTQXE5BUZARVJSDSTGHZQXQIU?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-de-transporte-en-aluminio-tipo-avion-ref-kp9806l';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe1462ff-m23-d-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar KBE1462FF-M23-D es la elección perfecta para quienes necesitan una silla resistente, cómoda y fácil de manejar. Fabricada en acero martillado, esta silla ofrece una estructura robusta que resiste el desgaste diario, siendo ideal para su uso en centros comerciales, aeropuertos, conjuntos residenciales y otros entornos donde se requiere asistencia a los usuarios.

La silla de ruedas estándar S23 Konfort Plus (KBE1462FF-M23-D) es de acero martillado, plegable con respaldo abatible y reposapiés fijos removibles que reducen el espacio de almacenamiento. Tiene tapicería de PVC, aros de propulsión, asas de empuje abatibles, cinturón para el usuario, capacidad de hasta 90 kg y 1 año de garantía. Es ideal para establecimientos que prestan asistencia a los usuarios.$d$,
  descripcion_larga_en = $d$The Standard Wheelchair KBE1462FF-M23-D is the perfect choice for those requiring a sturdy, comfortable, and easy-to-handle chair. Made from hammered steel, it features a robust structure that withstands daily wear, making it suitable for use in shopping centers, airports, residential complexes, and other environments where user assistance is required.

The Konfort Plus S23 standard wheelchair (KBE1462FF-M23-D) is hammered steel, foldable with folding backrest and fixed removable footrests that reduce storage space. It has PVC upholstery, propulsion rims, folding push handles, a user belt, capacity up to 90 kg and a 1-year warranty. It is ideal for establishments that assist users.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE1462FF-M23-D"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Estructura / tapicería","grupo":"Material","valor":"Acero martillado / PVC"},{"clave":"Cinturón","grupo":"Seguridad","valor":"Incluido"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Acero martillado plegable con respaldo abatible y reposapiés removibles.","Incluye cinturón para el usuario y aros de propulsión.","Capacidad de hasta 90 kg; 1 año de garantía."],"beneficios_en":["Foldable hammered steel with folding backrest and removable footrests.","Includes user belt and propulsion rims.","Up to 90 kg capacity; 1-year warranty."],"valor_es":"Una silla de ruedas estándar de acero con cinturón y aros de propulsión.","valor_en":"A standard steel wheelchair with belt and propulsion rims.","preguntas_frecuentes_es":[{"q":"¿Incluye cinturón?","a":"Sí, incluye cinturón para el usuario."},{"q":"¿Qué capacidad tiene?","a":"Hasta 90 kg."},{"q":"¿Qué tapicería tiene?","a":"PVC."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar Desarmable En Acero Con Tapicería En PVC Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Does it include a belt?","a":"Yes, it includes a user belt."},{"q":"What capacity does it have?","a":"Up to 90 kg."},{"q":"What upholstery does it have?","a":"PVC."},{"q":"Where can I download the Standard Foldable Steel Wheelchair With PVC Upholstery Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas estándar S23","silla de ruedas KBE1462FF-M23-D","silla de ruedas de acero con cinturón","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE1462FF-M23-D"],"seo_keywords_en":["S23 standard wheelchair","KBE1462FF-M23-D wheelchair","steel wheelchair with belt","Konfort Plus wheelchair","wheelchairs Colombia","KBE1462FF-M23-D datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCDBYZILZ5RNDIDKN5LE7OOOZNNI?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-estandar-desarmable-en-acero-con-tapiceria-en-p-ref-kbe1462ff-m23-d-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe1462rr-pp23l-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar KBE1462RR-PP23L es ideal para usuarios que necesitan una silla confiable para uso en interiores. Fabricada en acero martillado, ofrece durabilidad y resistencia al desgaste diario. Los reposapiés y apoyabrazos removibles facilitan las transferencias y optimizan el espacio para transporte y almacenamiento. Los apoyabrazos tipo escritorio permiten al usuario acercarse a mesas, fomentando la independencia en actividades diarias.

La silla de ruedas estándar S50 Konfort Plus (KBE1462RR-PP23L) está fabricada en acero martillado, con apoyabrazos y reposapiés removibles que facilitan la transferencia del usuario. Es ideal para interiores y exteriores, con tapicería de PVC negro, aros de propulsión, bolsillo trasero, capacidad de hasta 90 kg y 1 año de garantía.$d$,
  descripcion_larga_en = $d$The Standard Wheelchair KBE1462RR-PP23L is ideal for users requiring reliable indoor mobility. Made from hammered steel, it provides durability and resistance to daily wear. Removable footrests and armrests facilitate transfers and optimize space for transport and storage. Desk-type armrests allow users to approach tables, promoting independence in daily activities.

The Konfort Plus S50 standard wheelchair (KBE1462RR-PP23L) is made of hammered steel, with removable armrests and footrests that ease user transfer. It is suited to indoors and outdoors, with black PVC upholstery, propulsion rims, a rear pocket, capacity up to 90 kg and a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE1462RR-PP23L"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Estructura / tapicería","grupo":"Material","valor":"Acero martillado / PVC negro"},{"clave":"Peso neto","grupo":"Peso","valor":"16,70 kg"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Apoyabrazos y reposapiés removibles que facilitan la transferencia.","Para interiores y exteriores, con bolsillo trasero.","Capacidad de hasta 90 kg y 1 año de garantía."],"beneficios_en":["Removable armrests and footrests that ease transfer.","For indoor and outdoor use, with rear pocket.","Up to 90 kg capacity and 1-year warranty."],"valor_es":"Una silla de ruedas estándar con apoyabrazos y reposapiés removibles.","valor_en":"A standard wheelchair with removable armrests and footrests.","preguntas_frecuentes_es":[{"q":"¿Se usa en exteriores?","a":"Sí, está diseñada para uso en interiores y exteriores."},{"q":"¿Qué capacidad tiene?","a":"Hasta 90 kg."},{"q":"¿Tiene bolsillo?","a":"Sí, bolsillo trasero."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar En Acero Con Reposapiés y Apoyabrazos Removibles Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Is it used outdoors?","a":"Yes, it is designed for indoor and outdoor use."},{"q":"What capacity does it have?","a":"Up to 90 kg."},{"q":"Does it have a pocket?","a":"Yes, a rear pocket."},{"q":"Where can I download the Standard Steel Wheelchair With Removable Footrests And Armrests Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas estándar S50","silla de ruedas KBE1462RR-PP23L","silla de ruedas con apoyabrazos removibles","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE1462RR-PP23L"],"seo_keywords_en":["S50 standard wheelchair","KBE1462RR-PP23L wheelchair","wheelchair with removable armrests","Konfort Plus wheelchair","wheelchairs Colombia","KBE1462RR-PP23L datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCHWDPPWXC6FHJXNIZ5JELH5CL5U?version=2.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-estandar-en-acero-con-reposapies-y-apoyabrazos-ref-kbe1462rr-pp23l-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe-9630l-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar y de Transporte KBE-9630L es una solución versátil para quienes buscan una combinación de ligereza, durabilidad y facilidad de uso. Con una estructura de aluminio y asas de empuje en acero, esta silla es ligera y resistente, ideal para un manejo sencillo.

La silla de ruedas estándar y de transporte en aluminio Konfort Plus (KBE-9630L) tiene reposapiés, apoyabrazos y asas de empuje abatibles que, al plegarla, disminuyen el espacio ocupado. Sus frenos de cuidador permiten usarla como silla de transporte, y es ideal para adultos mayores que pueden autopropulsarse y a la vez requieren el cuidado de un tercero. Soporta 100 kg.$d$,
  descripcion_larga_en = $d$The Konfort Plus Standard and Transport Aluminum Wheelchair KBE-9630L is a versatile solution for those seeking a combination of lightness, durability and ease of use. Its aluminum structure and steel push handles make this wheelchair light and resistant, ideal for simple handling.

The Konfort Plus standard and transport aluminium wheelchair (KBE-9630L) has folding footrests, armrests and push handles that reduce the space taken when folded. Its caregiver brakes allow use as a transport chair, and it is ideal for older adults who can self-propel yet may need a third party to push them. It supports 100 kg.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-9630L"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio"},{"clave":"Freno","grupo":"Seguridad","valor":"De cuidador"}]$j$::jsonb,
