UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/srels-44-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Estándar Iron Light ofrece una solución confiable para usuarios que necesitan asistencia en su movilidad diaria. Fabricada en acero ligero pintado de alta resistencia, esta silla brinda seguridad y estabilidad en cualquier entorno. Sus reposapiés son abatibles, removibles y ajustables en altura, lo que facilita las transferencias y mejora la comodidad del usuario.

La silla de ruedas Iron Light Konfort Plus (SRELS-44, asiento de 44 cm) está fabricada en acero ligero pintado (calibre 2 mm), con estructura plegable, llantas traseras de 24" desmontables de desmonte rápido, apoyabrazos abatibles y removibles y reposapiés removibles ajustables en altura (43 a 46 cm). Soporta 113 kg y pesa cerca de 20 kg; es ideal para usuarios de vida activa.$d$,
  descripcion_larga_en = $d$The Iron Light Standard Wheelchair provides a reliable solution for users requiring daily mobility assistance. Constructed from lightweight, high-strength painted steel, it delivers security and stability across diverse environments. Its foldable, removable, and height-adjustable footrests facilitate transfers and enhance user comfort.

The Konfort Plus Iron Light wheelchair (SRELS-44, 44 cm seat) is made of lightweight painted steel (2 mm gauge), with a foldable structure, 24" quick-release rear wheels, folding and removable armrests and removable footrests adjustable in height (43 to 46 cm). It supports 113 kg and weighs about 20 kg; it is ideal for active users.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"SRELS-44"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"113 kg"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"44 cm"},{"clave":"Estructura","grupo":"Material","valor":"Acero ligero pintado, calibre 2 mm"},{"clave":"Traseras","grupo":"Ruedas","valor":"24\" desmontables"},{"clave":"Registro sanitario","grupo":"Regulatorio","valor":"2013DM-0010767; clase I"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Acero ligero, plegable, con ruedas traseras de 24\" de desmonte rápido.","Apoyabrazos abatibles/removibles y reposapiés ajustables en altura.","Capacidad de 113 kg."],"beneficios_en":["Light steel, foldable, with 24\" quick-release rear wheels.","Folding/removable armrests and height-adjustable footrests.","113 kg capacity."],"valor_es":"Una silla de ruedas Iron Light para usuarios activos.","valor_en":"An Iron Light wheelchair for active users.","preguntas_frecuentes_es":[{"q":"¿Qué ancho de asiento tiene?","a":"44 cm (la versión SRELS-47 tiene 47 cm)."},{"q":"¿Qué capacidad tiene?","a":"113 kg."},{"q":"¿Se desmontan las ruedas?","a":"Sí, las llantas traseras son desmontables de desmonte rápido."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Iron Light Ancho Del Asiento 44 cm Y Reposapiés Removibles Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What seat width does it have?","a":"44 cm (the SRELS-47 version has 47 cm)."},{"q":"What capacity does it have?","a":"113 kg."},{"q":"Are the wheels removable?","a":"Yes, the rear wheels are quick-release."},{"q":"Where can I download the Iron Light Wheelchair 44 cm Seat Width With Removable Footrests Konfort Plus datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas Iron Light","silla de ruedas SRELS-44","silla de ruedas plegable de acero ligero","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica SRELS-44"],"seo_keywords_en":["Iron Light wheelchair","SRELS-44 wheelchair","lightweight steel foldable wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","SRELS-44 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCU2ZAVDZQMRBJVAFIQSITASMWCY?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-iron-light-ancho-del-asiento-44-cm-y-reposapies-removi-ref-srels-44-konfort-plus';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-konfort-plus/kbe-9953-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Reclinable KBE-9953 es una opción ideal para usuarios que requieren comodidad y soporte ajustable durante el uso prolongado. Fabricada en acero martillado, esta silla es robusta y resistente, diseñada para proporcionar durabilidad y seguridad.

La silla de ruedas reclinable Konfort Plus KBE-9953 es de acero martillado con respaldo reclinable de 90° a 145°, reposapiés elevables y graduables en altura, soporte de cabeza removible, apoyabrazos removibles que permiten las transferencias laterales, frenos de cuidador y ruedas antivuelco. Tiene 125 cm de alto total y capacidad de 100 kg.$d$,
  descripcion_larga_en = $d$The KBE-9953 Reclining Wheelchair is an ideal option for users requiring comfort and adjustable support during prolonged use. Made of hammered steel, this wheelchair is robust and resistant, designed to provide durability and safety.

The Konfort Plus KBE-9953 reclining wheelchair is hammered steel with a 90° to 145° reclining backrest, elevating height-adjustable footrests, removable headrest, removable armrests that allow lateral transfers, caregiver brakes and anti-tip wheels. It has a 125 cm overall height and a 100 kg capacity.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KBE-9953"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Respaldo reclinable","grupo":"Ajustes","valor":"90° - 145°"},{"clave":"Alto total","grupo":"Dimensiones","valor":"125 cm"},{"clave":"Estructura","grupo":"Material","valor":"Acero martillado"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Respaldo reclinable de 90° a 145° y reposapiés elevables.","Soporte de cabeza removible y apoyabrazos removibles para transferencias laterales.","Frenos de cuidador y ruedas antivuelco; capacidad de 100 kg."],"beneficios_en":["90° to 145° reclining backrest and elevating footrests.","Removable headrest and armrests for lateral transfers.","Caregiver brakes and anti-tip wheels; 100 kg capacity."],"valor_es":"Una silla de ruedas reclinable de acero con reposapiés elevables.","valor_en":"A reclining steel wheelchair with elevating footrests.","preguntas_frecuentes_es":[{"q":"¿Cuánto reclina el respaldo?","a":"De 90° a 145°."},{"q":"¿Qué capacidad tiene?","a":"100 kg."},{"q":"¿Tiene soporte de cabeza?","a":"Sí, removible."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Estándar En Acero Reclinable Konfort Plus?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How far does the backrest recline?","a":"From 90° to 145°."},{"q":"What capacity does it have?","a":"100 kg."},{"q":"Does it have a headrest?","a":"Yes, removable."},{"q":"Where can I download the Konfort Plus Reclining Steel Standard Wheelchair KBE-9953 datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas reclinable","silla de ruedas KBE-9953","silla de ruedas con soporte de cabeza","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KBE-9953"],"seo_keywords_en":["reclining wheelchair","KBE-9953 wheelchair","wheelchair with headrest","Konfort Plus wheelchair","wheelchairs Colombia","KBE-9953 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCF2E3OWTADRHEJMJC2NNREOHVKY?version=1.1&channel