UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9031-18-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Iron Move está diseñada para ofrecer resistencia, funcionalidad y practicidad en el uso diario de personas con movilidad reducida. Su estructura en acero brinda firmeza y durabilidad, adecuada para un uso frecuente en el hogar, instituciones o entornos de cuidado. Cuenta con un marco plegable que facilita el transporte y el almacenamiento. Incorpora apoyabrazos tipo escritorio, que permiten un mejor acercamiento a mesas y superficies de trabajo, ruedas con rin estrella que aportan estabilidad durante el desplazamiento, y reposapiés abatibles y removibles, facilitando las transferencias y la adaptación a diferentes situaciones de uso.

La silla de ruedas Iron Move (estándar plus, rin estrella) Konfort Plus de 45,7 cm está diseñada para dar soporte, estabilidad y comodidad a personas con sobrepeso, con capacidad de hasta 135 kg. Sus apoyabrazos abatibles tipo escritorio facilitan la adaptación a las actividades cotidianas, y su estructura reforzada de acero con pintura electrostática y ruedas macizas favorece un uso seguro y funcional. Tiene frenos de cuidador y 2 años de garantía.$d$,
  descripcion_larga_en = $d$Wheelchair designed to offer resistance, functionality and practicality in the daily use of people with reduced mobility. Its steel structure provides firmness and durability, suitable for frequent use at home, institutions or care settings. Features a folding frame that facilitates transport and storage. Incorporates desk-type armrests, allowing better access to tables and work surfaces, star wheels that provide stability during movement, and swing-away, removable footrests, facilitating transfers and adaptation to different use situations.

The Konfort Plus Iron Move wheelchair (standard plus, star rim) in 45.7 cm is designed to provide support, stability and comfort to people with overweight, with capacity up to 135 kg. Its desk-type folding armrests make it easy to adapt to daily activities, and its reinforced electrostatic-painted steel structure and solid wheels favour safe, functional use. It has caregiver brakes and a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9031-18"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"45,7 cm"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"135 kg"},{"clave":"Estructura","grupo":"Material","valor":"Acero con pintura electrostática"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capacidad de hasta 135 kg con estructura de acero reforzada.","Apoyabrazos abatibles tipo escritorio y ruedas macizas.","Frenos de cuidador y 2 años de garantía."],"beneficios_en":["Capacity up to 135 kg with reinforced steel structure.","Desk-type folding armrests and solid wheels.","Caregiver brakes and 2-year warranty."],"valor_es":"Una silla de ruedas reforzada de hasta 135 kg.","valor_en":"A reinforced wheelchair up to 135 kg.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 135 kg."},{"q":"¿Qué anchos existen?","a":"45,7 cm (KP9031-18) y 50 cm (KP9031-20)."},{"q":"¿Qué garantía tiene?","a":"2 años."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Iron Move de 45,7 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 135 kg."},{"q":"Which widths exist?","a":"45.7 cm (KP9031-18) and 50 cm (KP9031-20)."},{"q":"What warranty does it have?","a":"2 years."},{"q":"Where can I download the Iron Move Wheelchair 45.7 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas Iron Move 45,7 cm","silla de ruedas estándar plus 135 kg","silla de ruedas reforzada","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KP9031-18"],"seo_keywords_en":["Iron Move wheelchair 45.7 cm","standard plus 135 kg wheelchair","reinforced wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KP9031-18 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCNKSP6GOPHBBI5HYSUKAJO7QJRQ?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
