UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9031-18-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Iron Move de ancho está diseñada para ofrecer resistencia, estabilidad y soporte a personas con movilidad reducida que requieren una silla robusta para el uso diario. Su estructura en acero proporciona firmeza y durabilidad, adecuada para un uso frecuente tanto en el hogar como en otros entornos. Iron Move cuenta con un sistema de doble cruceta, que refuerza la estructura del marco y aporta mayor estabilidad durante el desplazamiento y las transferencias.

La silla de ruedas Iron Move (estándar plus, rin estrella) Konfort Plus de 50 cm está diseñada para dar soporte, estabilidad y comodidad a personas con sobrepeso, con capacidad de hasta 135 kg. Sus apoyabrazos abatibles tipo escritorio facilitan la adaptación a las actividades cotidianas, y su estructura reforzada de acero con pintura electrostática y ruedas macizas favorece un uso seguro y funcional. Tiene frenos de cuidador y 2 años de garantía.$d$,
  descripcion_larga_en = $d$Wide wheelchair designed to offer resistance, stability and support to people with reduced mobility requiring a robust chair for daily use. Its steel structure provides firmness and durability, suitable for frequent use both at home and other settings. Iron Move features a double cross-brace system that reinforces the frame structure and provides greater stability during movement and transfers.

The Konfort Plus Iron Move wheelchair (standard plus, star rim) in 50 cm is designed to provide support, stability and comfort to people with overweight, with capacity up to 135 kg. Its desk-type folding armrests make it easy to adapt to daily activities, and its reinforced electrostatic-painted steel structure and solid wheels favour safe, functional use. It has caregiver brakes and a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9031-20"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"50 cm"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"135 kg"},{"clave":"Estructura","grupo":"Material","valor":"Acero con pintura electrostática"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Capacidad de hasta 135 kg con estructura de acero reforzada.","Apoyabrazos abatibles tipo escritorio y ruedas macizas.","Frenos de cuidador y 2 años de garantía."],"beneficios_en":["Capacity up to 135 kg with reinforced steel structure.","Desk-type folding armrests and solid wheels.","Caregiver brakes and 2-year warranty."],"valor_es":"Una silla de ruedas reforzada de hasta 135 kg.","valor_en":"A reinforced wheelchair up to 135 kg.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"Hasta 135 kg."},{"q":"¿Qué anchos existen?","a":"45,7 cm (KP9031-18) y 50 cm (KP9031-20)."},{"q":"¿Qué garantía tiene?","a":"2 años."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Iron Move de 50 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"Up to 135 kg."},{"q":"Which widths exist?","a":"45.7 cm (KP9031-18) and 50 cm (KP9031-20)."},{"q":"What warranty does it have?","a":"2 years."},{"q":"Where can I download the Iron Move Wheelchair 50 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas Iron Move 50 cm","silla de ruedas estándar plus 135 kg","silla de ruedas reforzada","silla de ruedas Konfort Plus","sillas de ruedas Colombia","ficha técnica KP9031-20"],"seo_keywords_en":["Iron Move wheelchair 50 cm","standard plus 135 kg wheelchair","reinforced wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KP9031-20 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCNKSP6GOPHBBI5HYSUKAJO7QJRQ?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-iron-move-de-50-cm-de-ancho-ref-kp9031-20';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9031-12-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas en Acero Pediátrica Lima está diseñada para acompañar a niñas y niños con movilidad reducida en sus actividades cotidianas, ofreciendo una solución resistente, segura y funcional para el uso diario. Su estructura en acero proporciona firmeza y durabilidad, adecuada para el ritmo activo y cambiante de la infancia. Lima cuenta con un marco plegable que facilita el transporte y el almacenamiento, adaptándose a los distintos espacios del hogar, la escuela y otros entornos. Su respaldo de tensión regulable y su cojín con contorno acompañan la postura y se adaptan a las necesidades del cuerpo en movimiento.

La silla de ruedas pediátrica en acero Lima Konfort Plus (asiento de 30,5 cm) ofrece movilidad segura y confortable a niños gracias a sus dimensiones, estructura compacta y estable. Su espaldar con tensión ajustable permite adaptar el soporte a la postura y la anatomía del usuario. Incluye frenos de cuidador, cinturón de seguridad, ruedas traseras de 20" con aros de propulsión y bomba de aire con kit para pinchaduras; tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$Pediatric steel wheelchair designed to accompany children with reduced mobility in daily activities, offering a resistant, safe and functional solution. Its steel structure provides firmness and durability, suitable for the active and changing pace of childhood. Lima features a folding frame that facilitates transport and storage, adapting to different home, school and other environments. The adjustable tension backrest and contoured cushion support posture and adapt to the needs of the body in motion.

The Konfort Plus Lima paediatric steel wheelchair (30.5 cm seat) offers safe, comfortable mobility to children thanks to its dimensions and compact, stable structure. Its adjustable-tension backrest lets you adapt the support to the user's posture and anatomy. It includes caregiver brakes, a safety belt, 20" rear wheels with propulsion rims and an air pump with puncture repair kit; it has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9031-12"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"30,5 cm"},{"clave":"Estructura","grupo":"Material","valor":"Acero"},{"clave":"Traseras","grupo":"Ruedas","valor":"20\" rin radio, neumáticas, con aros"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Espaldar con tensión ajustable para adaptar el soporte a la postura.","Frenos de cuidador, cinturón de seguridad y aros de propulsión.","Incluye bomba de aire y kit para pinchaduras; 2 años de garantía."],"beneficios_en":["Adjustable-tension backrest to adapt support to posture.","Caregiver brakes, safety belt and propulsion rims.","Air pump and puncture kit included; 2-year warranty."],"valor_es":"Una silla de ruedas pediátrica de acero con espaldar ajustable.","valor_en":"A paediatric steel wheelchair with adjustable backrest.","preguntas_frecuentes_es":[{"q":"¿Qué anchos de asiento hay?","a":"30,5 cm (KP9031-12) y 35,5 cm (KP9031-14)."},{"q":"¿Tiene cinturón de seguridad?","a":"Sí."},{"q":"¿Qué garantía tiene?","a":"2 años."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas en Acero Pediátrica Lima de 30,5 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which seat widths are there?","a":"30.5 cm (KP9031-12) and 35.5 cm (KP9031-14)."},{"q":"Does it have a safety belt?","a":"Yes."},{"q":"What warranty does it have?","a":"2 years."},{"q":"Where can I download the Pediatric Steel Wheelchair Lima 30.5 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas pediátrica 30,5 cm","silla de ruedas infantil de acero","silla de ruedas Lima","silla de ruedas Konfort Plus","sillas de ruedas pediátricas Colombia","ficha técnica KP9031-12"],"seo_keywords_en":["paediatric wheelchair 30.5 cm","children steel wheelchair","Lima wheelchair","Konfort Plus wheelchair","paediatric wheelchairs Colombia","KP9031-12 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCXVWKPCH54ZCT7IWVQF32OBXQHU?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-en-acero-pediatrica-lima-de-30-5-cm-de-ancho-ref-kp9031-12';

