UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9065-12-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas en Aluminio Pediátrica Uva está diseñada para acompañar a niñas y niños con movilidad reducida en sus actividades cotidianas, ofreciendo una solución resistente, segura y funcional para el uso diario. Su estructura en aluminio la hace más ligera. Uva cuenta con un marco plegable que facilita el transporte y el almacenamiento, adaptándose a los distintos espacios del hogar, la escuela y otros entornos. Su respaldo de tensión regulable y su cojín con contorno acompañan la postura y se adaptan a las necesidades del cuerpo en movimiento.

La silla de ruedas pediátrica Uva Konfort Plus (asiento de 30,4 cm) está fabricada en aluminio ligero con pintura electrostática morada y está diseñada para brindar movilidad segura y cómoda a niños y jóvenes. Su estructura compacta y plegable se combina con ruedas de coraza maciza en PU, apoyabrazos y reposapiés abatibles, cinturón de seguridad y tapicería ignífuga; la ficha indica capacidad de 100 kg y 2 años de garantía.$d$,
  descripcion_larga_en = $d$Pediatric aluminum wheelchair designed to accompany girls and boys with reduced mobility in their daily activities, offering a resistant, safe and functional solution for daily use. Its aluminum structure makes it lighter. Uva features a folding frame that facilitates transport and storage, adapting to different home, school and other environments. The adjustable tension backrest and contoured cushion support posture and adapt to the needs of the body in motion.

The Konfort Plus Uva paediatric wheelchair (30.4 cm seat) is made of lightweight aluminium with purple electrostatic paint and is designed to provide safe, comfortable mobility to children and young people. Its compact, foldable structure combines PU solid-tyre wheels, folding armrests and footrests, a safety belt and flame-retardant upholstery; the datasheet states a 100 kg capacity and a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9065-12"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"30,4 cm"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"100 kg"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio, pintura electrostática morada"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio ligero con pintura morada y estructura plegable.","Cinturón de seguridad, apoyabrazos y reposapiés abatibles, tapicería ignífuga.","Capacidad de 100 kg y 2 años de garantía."],"beneficios_en":["Lightweight aluminium with purple paint and foldable structure.","Safety belt, folding armrests and footrests, flame-retardant upholstery.","100 kg capacity and 2-year warranty."],"valor_es":"Una silla de ruedas pediátrica de aluminio, plegable y con cinturón.","valor_en":"A foldable paediatric aluminium wheelchair with belt.","preguntas_frecuentes_es":[{"q":"¿De qué color es?","a":"Morado."},{"q":"¿Qué anchos hay?","a":"30,4 cm (KP9065-12) y 35,5 cm (KP9065-14)."},{"q":"¿Qué capacidad tiene?","a":"100 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Pediátrica en Aluminio Uva de 30,4 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What colour is it?","a":"Purple."},{"q":"Which widths are there?","a":"30.4 cm (KP9065-12) and 35.5 cm (KP9065-14)."},{"q":"What capacity does it have?","a":"100 kg."},{"q":"Where can I download the Pediatric Aluminum Wheelchair Uva 30.4 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas pediátrica Uva 30,4 cm","silla de ruedas infantil de aluminio","silla de ruedas morada plegable","silla de ruedas Konfort Plus","sillas de ruedas pediátricas Colombia","ficha técnica KP9065-12"],"seo_keywords_en":["Uva paediatric wheelchair 30.4 cm","children aluminium wheelchair","purple folding wheelchair","Konfort Plus wheelchair","paediatric wheelchairs Colombia","KP9065-12 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCAQBZXMCJPRB7JLBRNCUIILON2I?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-pediatrica-en-aluminio-uva-de-30-4-cm-de-ancho-ref-kp9065-12';

