UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp140-14-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Basculante y Reclinable Énova está diseñada para ofrecer confort, adaptabilidad y facilidad de uso en procesos de movilidad y cuidado prolongado. Su estructura en aluminio combina ligereza y resistencia, mientras que su marco plegable facilita el transporte y el almacenamiento. Cuenta con ruedas traseras con pin de desmonte rápido, tiene sistema de basculación y reclinación, permitiendo ajustar la postura de la persona usuaria según sus necesidades de descanso, posicionamiento y estabilidad. Es una opción funcional para el hogar y entornos de atención especializada.

La silla de ruedas pediátrica basculante Énova Konfort Plus (KP140-14) brinda soporte postural avanzado, confort y seguridad a niños con necesidades neurológicas o limitaciones motoras. Su estructura de aluminio liviano, con sistema basculante y respaldo reclinable, permite ajustar la postura; incluye soporte cefálico, apoyos laterales, taco abductor y bandeja, además de frenos de cuidador y cinturón de seguridad. Soporta 90 kg y tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$Tilt and recline wheelchair designed to offer comfort, adaptability and ease of use in mobility and long-term care processes. Its aluminum structure combines lightness and resistance, while the folding frame facilitates transport and storage. Features quick-release rear wheels and a tilt and recline system, allowing adjustment of the user's posture according to their rest, positioning and stability needs. A functional option for home and specialized care environments.

The Konfort Plus Énova paediatric tilt-in-space wheelchair (KP140-14) provides advanced postural support, comfort and safety to children with neurological needs or motor limitations. Its lightweight aluminium structure, with tilt system and reclining backrest, lets you adjust posture; it includes a headrest, lateral supports, abductor wedge and tray, plus caregiver brakes and a safety belt. It supports 90 kg and has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP140-14"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"35,5 cm"},{"clave":"Peso neto","grupo":"Peso","valor":"24 kg"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Sistema basculante y respaldo reclinable para ajustar la postura.","Soporte cefálico, apoyos laterales, taco abductor y bandeja.","Aluminio liviano, frenos de cuidador y cinturón; 2 años de garantía."],"beneficios_en":["Tilt system and reclining backrest to adjust posture.","Headrest, lateral supports, abductor wedge and tray.","Lightweight aluminium, caregiver brakes and belt; 2-year warranty."],"valor_es":"Una silla de ruedas pediátrica basculante y reclinable con soporte postural.","valor_en":"A paediatric tilt-in-space reclining wheelchair with postural support.","preguntas_frecuentes_es":[{"q":"¿Para quién está pensada?","a":"Para niños con necesidades neurológicas o limitaciones motoras que requieren soporte postural."},{"q":"¿Qué accesorios incluye?","a":"Soporte cefálico, soportes laterales, taco abductor y bandeja."},{"q":"¿Qué capacidad tiene?","a":"90 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Basculante y Reclinable Énova de 35,5 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Who is it designed for?","a":"Children with neurological needs or motor limitations who need postural support."},{"q":"Which accessories does it include?","a":"Headrest, lateral supports, abductor wedge and tray."},{"q":"What capacity does it have?","a":"90 kg."},{"q":"Where can I download the Tilt and Recline Wheelchair Énova 35.5 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas pediátrica basculante","silla de ruedas Énova KP140-14","silla de ruedas con soporte postural","silla de ruedas Konfort Plus","sillas de ruedas neurológicas Colombia","ficha técnica KP140-14"],"seo_keywords_en":["paediatric tilt-in-space wheelchair","Énova KP140-14 wheelchair","wheelchair with postural support","Konfort Plus wheelchair","wheelchairs Colombia","KP140-14 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MC4RFFATERM5EWNOP4EETZK7L3I4?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-basculante-y-reclinable-enova-de-35-5-cm-de-ancho-ref-kp140-14';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp140-16-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Basculante y Reclinable está diseñada para acompañar a personas que requieren mayor soporte postural, cambios frecuentes de posición y un nivel profundo de confort durante el uso prolongado. Su sistema de basculación permite inclinar todo el asiento para redistribuir presiones y brindar descanso, mientras que la reclinación del espaldar favorece una postura más abierta y relajada, ideal para quienes necesitan variar el ángulo del tronco sin esfuerzo. Está construida con una estructura resistente y liviana, fácil de maniobrar por acompañantes o cuidadores. Los soportes, laterales y otros soportes ajustables se adaptan a las necesidades del cuerpo para ofrecer estabilidad y seguridad.

La silla de ruedas de adulto basculante y reclinable Konfort Plus (KP140-16, ancho de asiento de 40,6 cm) brinda soporte postural avanzado, confort y seguridad a usuarios con necesidades neurológicas o limitaciones motoras. Su estructura de aluminio liviano, con sistema basculante y respaldo reclinable, permite ajustar la postura; incluye soporte cefálico, apoyos laterales, taco abductor y bandeja, además de frenos de cuidador y cinturón de seguridad. Soporta 90 kg y tiene 2 años de garantía.$d$,
  descripcion_larga_en = $d$Wheelchair with tilt and recline designed to accompany people requiring greater postural support, frequent position changes and a deep level of comfort during prolonged use. The tilting system allows the entire seat to incline for pressure redistribution and rest, while the backrest recline promotes a more open and relaxed posture, ideal for those needing to vary trunk angle without effort. Constructed with a resistant and lightweight structure, easy to maneuver by companions or caregivers. Adjustable lateral supports and other supports adapt to body needs for stability and safety.

The Konfort Plus adult tilt-in-space reclining wheelchair (KP140-16, 40.6 cm seat width) provides advanced postural support, comfort and safety to users with neurological needs or motor limitations. Its lightweight aluminium structure, with tilt system and reclining backrest, lets you adjust posture; it includes a headrest, lateral supports, abductor wedge and tray, plus caregiver brakes and a safety belt. It supports 90 kg and has a 2-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP140-16"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"90 kg"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"40,6 cm"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio"},{"clave":"Garantía","grupo":"Garantía","valor":"2 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Basculante y reclinable para ajustar la postura del usuario adulto.","Soporte cefálico, apoyos laterales, taco abductor y bandeja.","Aluminio liviano, frenos de cuidador y cinturón; 2 años de garantía."],"beneficios_en":["Tilt and recline to adjust the adult user's posture.","Headrest, lateral supports, abductor wedge and tray.","Lightweight aluminium, caregiver brakes and belt; 2-year warranty."],"valor_es":"Una silla de ruedas basculante y reclinable para adultos con soporte postural.","valor_en":"A tilt-in-space reclining wheelchair for adults with postural support.","preguntas_frecuentes_es":[{"q":"¿Qué anchos de asiento hay?","a":"40,6 cm (KP140-16) y la referencia KP140-18 de la misma ficha."},{"q":"¿Qué capacidad tiene?","a":"90 kg."},{"q":"¿Tiene bandeja?","a":"Sí, incluye bandeja entre los accesorios."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Basculante y Reclinable de 40,6 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"Which seat widths are there?","a":"40.6 cm (KP140-16) and the KP140-18 reference in the same datasheet."},{"q":"What capacity does it have?","a":"90 kg."},{"q":"Does it have a tray?","a":"Yes, a tray is among the accessories."},{"q":"Where can I download the Tilt and Recline Wheelchair 40.6 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas basculante adulto","silla de ruedas KP140-16","silla de ruedas reclinable con soporte cefálico","silla de ruedas Konfort Plus","sillas de ruedas neurológicas Colombia","ficha técnica KP140-16"],"seo_keywords_en":["adult tilt-in-space wheelchair","KP140-16 wheelchair","reclining wheelchair with headrest","Konfort Plus wheelchair","wheelchairs Colombia","KP140-16 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCYUAZXHXGZBHXPMW4OA6OHL7CSM?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-basculante-y-reclinable-de-40-6-cm-de-ancho-ref-kp140-16';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp-ii-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Activa Marco Rígido Oliva -16 está diseñada para personas con un nivel alto de actividad que buscan una silla ultraliviana, resistente y confiable para el uso cotidiano. Su estructura en aluminio ofrece un equilibrio preciso entre firmeza y ligereza, favoreciendo el control y la autonomía en el movimiento. Oliva cuenta con marco rígido y respaldo abatible, lo que permite reducir su volumen para transporte y almacenamiento, manteniendo la rigidez estructural necesaria para una silla activa. Su respaldo de tensión regulable y su cojín con contorno acompañan la postura y se adaptan a las necesidades del cuerpo en movimiento.

La silla de ruedas activa de marco rígido Konfort Plus color verde oliva de 16" está diseñada para usuarios que requieren mayor independencia, eficiencia de movimiento y confort. Fabricada en aluminio liviano de alta resistencia, ofrece un marco rígido y estable que mejora la transferencia de energía en cada impulso. Pesa 12 kg, soporta 110 kg, tiene ruedas traseras de 24" con rin de radios y desmonte rápido, eje trasero ajustable, ruedas antivuelco y 3 años de garantía.$d$,
  descripcion_larga_en = $d$Active rigid frame wheelchair designed for people with high activity level seeking an ultralight, resistant and reliable chair for everyday use. Its aluminum structure offers precise balance between firmness and lightness, favoring control and autonomy in movement. Oliva features a rigid frame and foldable backrest, allowing volume reduction for transport and storage while maintaining the structural rigidity needed for an active wheelchair. The adjustable tension backrest and contoured cushion support posture and adapt to the needs of the body in motion.

The Konfort Plus olive green 16" rigid-frame active wheelchair is designed for users who need greater independence, movement efficiency and comfort. Made of lightweight high-strength aluminium, it offers a rigid, stable frame that improves energy transfer with each push. It weighs 12 kg, supports 110 kg, has 24" spoked rear wheels with quick release, adjustable rear axle, anti-tip wheels and a 3-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP-II"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"110 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"12 kg"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"41 cm (16\")"},{"clave":"Garantía","grupo":"Garantía","valor":"3 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Marco rígido de aluminio de solo 12 kg que mejora la eficiencia de cada impulso.","Eje trasero ajustable, ruedas antivuelco y ruedas traseras de 24\" de desmonte rápido.","Capacidad de 110 kg y 3 años de garantía."],"beneficios_en":["Rigid aluminium frame of only 12 kg that improves the efficiency of each push.","Adjustable rear axle, anti-tip wheels and 24\" quick-release rear wheels.","110 kg capacity and 3-year warranty."],"valor_es":"Una silla de ruedas activa de marco rígido, ligera y ajustable.","valor_en":"A light, adjustable rigid-frame active wheelchair.","preguntas_frecuentes_es":[{"q":"¿Cuánto pesa?","a":"12 kg."},{"q":"¿Qué capacidad tiene?","a":"110 kg."},{"q":"¿Qué garantía tiene?","a":"3 años."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Activa Marco Rígido Oliva - 16\"?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"How much does it weigh?","a":"12 kg."},{"q":"What capacity does it have?","a":"110 kg."},{"q":"What warranty does it have?","a":"3 years."},{"q":"Where can I download the Active Rigid Frame Wheelchair Oliva - 16\" datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas activa marco rígido","silla de ruedas deportiva KP-II","silla de ruedas de aluminio 16\"","silla de ruedas Konfort Plus","sillas de ruedas activas Colombia","ficha técnica KP-II"],"seo_keywords_en":["rigid frame active wheelchair","sports wheelchair KP-II","16\" aluminium wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KP-II datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCE3HR533PMFE45CBDJDGL6M7LZM?version=3.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-activa-marco-rigido-oliva-16-ref-kp-ii';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kp9071-16-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Activa Plegable Luna Lite está diseñada para personas que buscan una solución liviana, funcional y adaptable para el uso diario. Su estructura en aluminio ofrece un equilibrio entre resistencia y ligereza, favoreciendo una movilidad más ágil y controlada. Cuenta con un marco plegable que facilita el transporte y el almacenamiento, junto con ruedas traseras con pin de desmonte rápido, permitiendo reducir el volumen de la silla de manera sencilla. Su rueda delantera de 8" facilita el desplazamiento sobre superficies irregulares, pasando obstáculos con mayor suavidad y estabilidad. Su respaldo de tensión regulable y su cojín con contorno acompañan la postura y se adaptan a las necesidades del cuerpo en movimiento, brindando mayor confort durante el desplazamiento.

La silla de ruedas activa plegable Luna 40,6 cm de Konfort Plus está fabricada en aluminio con tijera de acero y pintura electrostática, y está diseñada para usuarios activos que buscan independencia y control. Sus llantas traseras neumáticas de 24" con desmonte rápido, apoyabrazos abatibles de altura ajustable, reposapiés removibles y ruedas antivuelco la hacen compacta, segura y de alto desempeño. Soporta 130 kg y tiene 3 años de garantía.$d$,
  descripcion_larga_en = $d$Lite active wheelchair designed for daily use seeking a lightweight, functional and adaptable solution. Its aluminum frame offers the ideal balance between resistance and lightness, favoring more agile and controlled mobility. The folding frame facilitates transport and storage, paired with quick-release rear wheels, allowing easy volume reduction. The 8" front wheel facilitates movement on irregular surfaces, overcoming obstacles smoothly and stably. The adjustable tension backrest and contoured cushion support posture and adapt to the body in motion, offering greater comfort during travel.

The Konfort Plus Luna 40.6 cm folding active wheelchair is made of aluminium with a steel cross-brace and electrostatic paint, and is designed for active users seeking independence and control. Its 24" quick-release pneumatic rear tyres, height-adjustable folding armrests, removable footrests and anti-tip wheels make it compact, safe and high-performing. It supports 130 kg and has a 3-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KP9071-16"},{"clave":"Ancho de asiento","grupo":"Dimensiones","valor":"40,6 cm"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"130 kg"},{"clave":"Estructura","grupo":"Material","valor":"Aluminio con tijera de acero"},{"clave":"Garantía","grupo":"Garantía","valor":"3 años"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio con tijera de acero, llantas traseras neumáticas de 24\" con desmonte rápido.","Apoyabrazos abatibles de altura ajustable y ruedas antivuelco.","Capacidad de 130 kg y 3 años de garantía."],"beneficios_en":["Aluminium with steel cross-brace, 24\" quick-release pneumatic rear tyres.","Height-adjustable folding armrests and anti-tip wheels.","130 kg capacity and 3-year warranty."],"valor_es":"Una silla de ruedas activa plegable de aluminio para 130 kg.","valor_en":"A foldable active aluminium wheelchair for 130 kg.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"130 kg."},{"q":"¿Qué anchos existen?","a":"40,6 cm (KP9071-16) y 45,7 cm (KP9071-18)."},{"q":"¿Qué garantía tiene?","a":"3 años."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Activa Plegable Luna de 40,6 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"130 kg."},{"q":"Which widths exist?","a":"40.6 cm (KP9071-16) and 45.7 cm (KP9071-18)."},{"q":"What warranty does it have?","a":"3 years."},{"q":"Where can I download the Active Folding Wheelchair Luna 40.6 cm wide datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas activa plegable Luna 40,6 cm","silla de ruedas Luna de aluminio","silla de ruedas activa 130 kg","silla de ruedas Konfort Plus","sillas de ruedas activas Colombia","ficha técnica KP9071-16"],"seo_keywords_en":["folding active wheelchair Luna 40.6 cm","Luna aluminium wheelchair","130 kg active wheelchair","Konfort Plus wheelchair","active wheelchairs Colombia","KP9071-16 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCQV3SSUANQBFFHOB3DSRQ3JWGIQ?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-activa-plegable-luna-de-40-6-cm-de-ancho-ref-kp9071-16';

