UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kpm-a6-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Motorizada en Acero con Batería recargable está diseñada para brindar movilidad asistida, estabilidad y comodidad a personas con movilidad reducida que requieren apoyo motorizado en su desplazamiento diario. Su estructura en acero ofrece firmeza y durabilidad, adecuada para un uso frecuente. Cuenta con un marco plegable que facilita el transporte y el almacenamiento cuando no está en uso. Con apoyabrazos abatibles y reposapiés abatibles y removibles, lo que simplifica las transferencias y permite una adaptación más flexible a distintas situaciones de uso. Sus llantas traseras neumáticas de 12 pulgadas aportan mayor estabilidad y una conducción más suave en diferentes superficies.

La silla de ruedas motorizada Konfort Plus KPM-A6, en acero con batería recargable, brinda movilidad asistida, estabilidad y comodidad a personas con movilidad reducida. Su marco plegable facilita el transporte y almacenamiento, los apoyabrazos y reposapiés son abatibles y removibles y sus llantas traseras neumáticas de 12" aportan una conducción más suave. Pesa 32 kg, soporta 120 kg, supera pendientes de hasta 10° y tiene 1 año de garantía.$d$,
  descripcion_larga_en = $d$The Steel Motorized Wheelchair with rechargeable battery provides assisted mobility, stability and comfort for users with reduced mobility requiring powered support in daily displacement. Its steel frame offers firmness and durability for frequent use, while the foldable design facilitates transport and storage. It includes flip-back armrests and removable, foldable footrests to simplify transfers and adapt to various situations. The 12-inch pneumatic rear wheels ensure greater stability and smoother handling on different surfaces.

The Konfort Plus KPM-A6 power wheelchair, in steel with a rechargeable battery, provides assisted mobility, stability and comfort to people with reduced mobility. Its folding frame eases transport and storage, the armrests and footrests are folding and removable and its 12" pneumatic rear tyres give a smoother ride. It weighs 32 kg, supports 120 kg, climbs slopes up to 10° and has a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KPM-A6"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"120 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"32 kg"},{"clave":"Pendiente máxima","grupo":"Rendimiento","valor":"10°"},{"clave":"Ancho total / plegada","grupo":"Dimensiones","valor":"76 cm / 44 cm"},{"clave":"Carga","grupo":"Eléctrico","valor":"110 V ±10 %, 60 Hz"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Marco plegable de acero con batería recargable (carga a 110 V).","Apoyabrazos y reposapiés abatibles y removibles; llantas traseras neumáticas de 12\".","Capacidad de 120 kg y pendiente máxima de 10°."],"beneficios_en":["Foldable steel frame with rechargeable battery (110 V charging).","Folding and removable armrests and footrests; 12\" pneumatic rear tyres.","120 kg capacity and 10° maximum slope."],"valor_es":"Una silla de ruedas motorizada plegable de acero con batería recargable.","valor_en":"A foldable steel power wheelchair with rechargeable battery.","preguntas_frecuentes_es":[{"q":"¿Qué capacidad tiene?","a":"120 kg."},{"q":"¿Qué pendiente supera?","a":"Hasta 10°."},{"q":"¿Cuánto pesa?","a":"32 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla De Ruedas Motorizada en Acero con batería recargable?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What capacity does it have?","a":"120 kg."},{"q":"What slope does it climb?","a":"Up to 10°."},{"q":"How much does it weigh?","a":"32 kg."},{"q":"Where can I download the Steel Motorized Wheelchair with rechargeable battery datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas motorizada de acero","silla de ruedas eléctrica KPM-A6","silla de ruedas con batería recargable","silla de ruedas Konfort Plus","sillas de ruedas eléctricas Colombia","ficha técnica KPM-A6"],"seo_keywords_en":["steel power wheelchair","KPM-A6 electric wheelchair","rechargeable battery wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KPM-A6 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCVFM72GUBHREH3ES6NMHFBJKDB4?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
WHERE slug = 'silla-de-ruedas-motorizada-en-acero-con-bateria-recargable-ref-kpm-a6';

UPDATE public.productos SET
  ficha_pdf = '/assets/productos/fichas/gmd-gmd/kpm-a8-ft.pdf',
  descripcion_larga_es = $d$La Silla de Ruedas Motorizada con Batería de Litio en Aluminio está diseñada para ofrecer movilidad asistida eficiente, ligereza y comodidad en el uso diario. Su estructura en aluminio reduce el peso total de la silla, facilitando la maniobrabilidad y el transporte, sin comprometer la resistencia. Equipada con batería de litio, proporciona una solución más liviana y de carga eficiente, ideal para personas que requieren desplazamientos frecuentes y mayor practicidad en su rutina cotidiana. Con apoyabrazos abatibles, que facilitan las transferencias y el acceso lateral, y llantas traseras neumáticas de 12 pulgadas, que aportan mayor estabilidad y una conducción más suave en diferentes superficies.

La silla de ruedas motorizada Konfort Plus KPM-A8, en aluminio con batería de litio, ofrece movilidad asistida eficiente, ligereza y comodidad. Su estructura de aluminio reduce el peso total a 29 kg, facilitando la maniobrabilidad y el transporte, y la batería de litio ofrece una carga más eficiente. Tiene apoyabrazos abatibles, llantas traseras neumáticas de 12", capacidad de 135 kg, pendiente máxima de 10° y 1 año de garantía.$d$,
  descripcion_larga_en = $d$The motorized wheelchair features a lightweight aluminum structure and a lithium-ion battery for efficient assisted mobility and easy transport. It includes foldable armrests to facilitate transfers and 12-inch pneumatic rear wheels for enhanced stability on various surfaces. The design balances durability with maneuverability for indoor and outdoor use.

The Konfort Plus KPM-A8 power wheelchair, in aluminium with a lithium battery, offers efficient assisted mobility, lightness and comfort. Its aluminium structure reduces the total weight to 29 kg, easing manoeuvrability and transport, and the lithium battery offers more efficient charging. It has folding armrests, 12" pneumatic rear tyres, 135 kg capacity, 10° maximum slope and a 1-year warranty.$d$,
  especificaciones = $j$[{"clave":"Marca / fabricante","grupo":"Identificación","valor":"Konfort Plus (GMD)"},{"clave":"Referencia","grupo":"Identificación","valor":"KPM-A8"},{"clave":"Capacidad de peso","grupo":"Capacidad","valor":"135 kg"},{"clave":"Peso neto","grupo":"Peso","valor":"29 kg"},{"clave":"Pendiente máxima","grupo":"Rendimiento","valor":"10°"},{"clave":"Batería","grupo":"Energía","valor":"Litio"},{"clave":"Garantía","grupo":"Garantía","valor":"1 año"}]$j$::jsonb,
  atributos = COALESCE(atributos, '{}'::jsonb) || $j${"beneficios_es":["Aluminio y batería de litio: solo 29 kg para maniobrar y transportar.","Apoyabrazos abatibles y llantas traseras neumáticas de 12\".","Capacidad de 135 kg y pendiente máxima de 10°."],"beneficios_en":["Aluminium and lithium battery: only 29 kg to manoeuvre and transport.","Folding armrests and 12\" pneumatic rear tyres.","135 kg capacity and 10° maximum slope."],"valor_es":"Una silla de ruedas motorizada de aluminio con batería de litio.","valor_en":"A lithium-battery aluminium power wheelchair.","preguntas_frecuentes_es":[{"q":"¿Qué batería tiene?","a":"De litio."},{"q":"¿Cuánto pesa?","a":"29 kg."},{"q":"¿Qué capacidad tiene?","a":"135 kg."},{"q":"¿Dónde descargo la ficha técnica de Silla de Ruedas Motorizada Con Batería de Litio de 44,5 cm de ancho?","a":"En esta página, con el botón «Descargar ficha técnica»: es el PDF oficial de GMD (marca Konfort Plus) (en español)."}],"preguntas_frecuentes_en":[{"q":"What battery does it have?","a":"Lithium."},{"q":"How much does it weigh?","a":"29 kg."},{"q":"What capacity does it have?","a":"135 kg."},{"q":"Where can I download the Motorized Wheelchair with 44.5 cm Width Lithium Battery datasheet?","a":"On this page, with the “Download datasheet” button: it is the official GMD (marca Konfort Plus) PDF (in Spanish)."}],"seo_keywords_es":["silla de ruedas motorizada de aluminio","silla de ruedas eléctrica con batería de litio","silla de ruedas KPM-A8","silla de ruedas Konfort Plus","sillas de ruedas eléctricas Colombia","ficha técnica KPM-A8"],"seo_keywords_en":["aluminium power wheelchair","lithium battery electric wheelchair","KPM-A8 wheelchair","Konfort Plus wheelchair","wheelchairs Colombia","KPM-A8 datasheet"],"ficha_fabricante":{"fabricante":"GMD (marca Konfort Plus)","idioma":"es","url_origen":"https://www.gmd.com.co/sfsites/c/cms/delivery/media/MCEW6S5FPDBND3LOQ4Y3YGSRQ6L4?version=1.1&channelId=0apVT00000000Xu&oid=00D3t000001N5bX","descargada":"2026-10-02"}}$j$::jsonb
